const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'y' },
      { kind: 'text', payload: 't' },
      { kind: 'text', payload: 'O' },
      { kind: 'text', payload: '1.5' },
      { kind: 'text', payload: '1' },
      { kind: 'text', payload: '0.5' },
      { kind: 'text', payload: 'y₁ = sin t（振幅 1）' },
      { kind: 'text', payload: 'y₂ = 0.5 sin t（振幅 0.5）' },
      { kind: 'text', payload: 'y₁+y₂（合成振幅 1.5）' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var x0 = 90;
    var x1 = Math.max(x0 + 160, W - 190);
    var cy = H / 2;
    var sy = Math.max(20, (H - 100) / 2 / 1.7);
    var yAxisX = x0 - 32;
    var xp = x0 + (x1 - x0) / 4;
    var i, t, x, y;

    function head(tx, ty, dx, dy, s) {
      var px = -dy, py = dx;
      return visualSdk.polyline([
        [tx - dx * s + px * s * 0.45, ty - dy * s + py * s * 0.45],
        [tx, ty],
        [tx - dx * s - px * s * 0.45, ty - dy * s - py * s * 0.45]
      ]);
    }

    function dashed(ax, ay, bx, by, dash, gap) {
      var dx = bx - ax, dy = by - ay;
      var len = Math.sqrt(dx * dx + dy * dy);
      var ux = dx / len, uy = dy / len;
      var out = [];
      var s = 0;
      while (s < len) {
        var e = Math.min(s + dash, len);
        out = out.concat(visualSdk.polyline([[ax + ux * s, ay + uy * s], [ax + ux * e, ay + uy * e]]));
        s = e + gap;
      }
      return out;
    }

    function wave(amp) {
      var arr = [];
      var N = 240;
      for (i = 0; i <= N; i++) {
        t = i / N * 2 * Math.PI;
        x = x0 + (i / N) * (x1 - x0);
        y = cy - amp * sy * Math.sin(t);
        arr.push([x, y]);
      }
      return visualSdk.polyline(arr);
    }

    var axes = visualSdk.polyline([[yAxisX, cy], [x1 + 30, cy]])
      .concat(head(x1 + 30, cy, 1, 0, 10))
      .concat(visualSdk.polyline([[yAxisX, cy + 1.6 * sy], [yAxisX, cy - 1.6 * sy]]))
      .concat(head(yAxisX, cy - 1.6 * sy, 0, -1, 10));

    var ticks = [];
    var vals = [1.5, 1, 0.5];
    for (i = 0; i < vals.length; i++) {
      ticks = ticks.concat(visualSdk.polyline([[yAxisX - 6, cy - vals[i] * sy], [yAxisX + 6, cy - vals[i] * sy]]));
    }

    var guide = dashed(xp, cy, xp, cy - 1.5 * sy, 7, 6);

    var w1 = wave(1);
    var w2 = wave(0.5);
    var ws = wave(1.5);

    var peak1 = visualSdk.circle(xp, cy - sy, 3.5);
    var peak2 = visualSdk.circle(xp, cy - 0.5 * sy, 3.5);
    var peakS = visualSdk.circle(xp, cy - 1.5 * sy, 4);

    var labels = [
      { type: 'label', text: 'y', x: yAxisX, y: cy - 1.6 * sy - 12, fontSize: 14, fill: '#26354a', anchor: 'middle' },
      { type: 'label', text: 't', x: x1 + 38, y: cy + 6, fontSize: 14, fill: '#26354a', anchor: 'start' },
      { type: 'label', text: 'O', x: yAxisX - 10, y: cy + 18, fontSize: 13, fill: '#26354a', anchor: 'end' },
      { type: 'label', text: '1.5', x: yAxisX - 10, y: cy - 1.5 * sy + 4, fontSize: 13, fill: '#26354a', anchor: 'end' },
      { type: 'label', text: '1', x: yAxisX - 10, y: cy - sy + 4, fontSize: 13, fill: '#26354a', anchor: 'end' },
      { type: 'label', text: '0.5', x: yAxisX - 10, y: cy - 0.5 * sy + 4, fontSize: 13, fill: '#26354a', anchor: 'end' },
      { type: 'label', text: 'y₁ = sin t（振幅 1）', x: xp + 20, y: cy - sy - 10, fontSize: 13, fill: '#2f6fb5', anchor: 'start' },
      { type: 'label', text: 'y₂ = 0.5 sin t（振幅 0.5）', x: xp + 20, y: cy - 0.5 * sy - 10, fontSize: 13, fill: '#2f8f5b', anchor: 'start' },
      { type: 'label', text: 'y₁+y₂（合成振幅 1.5）', x: xp + 20, y: cy - 1.5 * sy - 10, fontSize: 13, fill: '#c1440e', anchor: 'start' }
    ];

    return {
      schemaVersion: 1,
      sceneId: 'sine-sum-transcription',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'axes', commands: axes },
        { id: 'ticks', commands: ticks },
        { id: 'guide', commands: guide },
        { id: 'w2', commands: w2 },
        { id: 'w1', commands: w1 },
        { id: 'ws', commands: ws },
        { id: 'pk1', commands: peak1 },
        { id: 'pk2', commands: peak2 },
        { id: 'pks', commands: peakS }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'guide', stroke: '#9aa4b2', strokeWidth: 1.2 },
          { type: 'path', pathId: 'axes', stroke: '#26354a', strokeWidth: 1.6 },
          { type: 'path', pathId: 'ticks', stroke: '#26354a', strokeWidth: 1.4 },
          { type: 'path', pathId: 'w2', stroke: '#2f8f5b', strokeWidth: 2, fill: 'none' },
          { type: 'path', pathId: 'w1', stroke: '#2f6fb5', strokeWidth: 2, fill: 'none' },
          { type: 'path', pathId: 'ws', stroke: '#c1440e', strokeWidth: 2.4, fill: 'none' },
          { type: 'path', pathId: 'pk1', fill: '#2f6fb5', stroke: '#2f6fb5' },
          { type: 'path', pathId: 'pk2', fill: '#2f8f5b', stroke: '#2f8f5b' },
          { type: 'path', pathId: 'pks', fill: '#c1440e', stroke: '#c1440e' }
        ].concat(labels)
      }
    };
  }
};
